    _dashboardFuture = Future.wait([
      currencyRepository.fetchRates(const CurrencyPageRequest()),
      newsRepository.loadNewsFeed(const NewsFeedFilter(forceRefresh: true)),
    ]).then((List<dynamic> results) {
      return <String, dynamic>{
        'currencies': (results[0] as CurrencyPage).items,
        'news': results[1] as List<NewsModel>,
      };
    });
  }

  @override
  Widget build(BuildContext context) {
    final AppLocalizations loc = context.loc;
    final ThemeFonts fonts = context.fonts;

    return Scaffold(
      appBar: AppBar(title: Text(loc.dashboard)),
      body: FutureBuilder<Map<String, dynamic>>(
        future: _dashboardFuture,
        builder: (BuildContext context, AsyncSnapshot<Map<String, dynamic>> snapshot) {
          if (snapshot.hasError) {
            return Center(child: Text('${loc.error}: ${snapshot.error}'));
          }

          if (!snapshot.hasData) {
            return const Center(
              child: CircularProgressIndicator(),
            );
          }

          final List<CurrencyModel> currencies = snapshot.data!['currencies'] as List<CurrencyModel>;
          final List<NewsModel> news = snapshot.data!['news'] as List<NewsModel>;

          _fadeController.forward();

          return FadeTransition(
            opacity: _fadeController.view,
            child: ListView(
              padding: const EdgeInsets.all(16),
              children: [
                Text(loc.currencies, style: fonts.semiBold12),
                const SizedBox(height: 8),
                ...currencies.map((CurrencyModel currency) {
                  return Padding(
                    key: ValueKey(currency.id),
                    padding: const EdgeInsets.only(bottom: 8),
                    child: CurrencyCard(model: currency),
                  );
                }),
                const Divider(),
                Text(loc.news, style: fonts.semiBold12),
                const SizedBox(height: 8),
                ...news.map((NewsModel newsItem) {
                  return Padding(
                    key: ValueKey(newsItem.link),
                    padding: const EdgeInsets.only(bottom: 8),
                    child: NewsCard(model: newsItem),
                  );
                }),
              ],
            ),
          );
        },
      ),
    );
  }
}
